const finalizeCancelledConnectorJobs = `-- name: FinalizeCancelledConnectorJobs :many
WITH cancelled AS (
    SELECT job.id
    FROM connector_jobs job
    WHERE job.status IN ('running', 'finalizing')
      AND job.cancel_requested_at IS NOT NULL
      AND NOT EXISTS (
          SELECT 1 FROM connector_job_attempts attempt
          WHERE attempt.job_id = job.id
            AND attempt.status IN ('leased', 'running')
            AND attempt.lease_expires_at > now()
      )
      AND NOT EXISTS (
          SELECT 1 FROM connector_transfers transfer
          WHERE transfer.job_id = job.id
            AND transfer.state = 'finalizing'
            AND transfer.finalization_lease_expires_at > now()
      )
    ORDER BY job.cancel_requested_at, job.id
    FOR UPDATE OF job SKIP LOCKED
    LIMIT LEAST($1::integer, 100)
), finished AS (
UPDATE connector_jobs job
SET status = CASE WHEN job.error_code = 'offline' THEN 'skipped' ELSE 'cancelled' END,
    error_code = CASE WHEN job.error_code = 'offline' THEN job.error_code ELSE 'cancelled' END,
    error_message = CASE WHEN job.error_code = 'offline' THEN job.error_message ELSE 'cancelled' END,
    completed_at = now(), updated_at = now()
FROM cancelled
WHERE job.id = cancelled.id
RETURNING job.id, job.connector_id, job.agent_id, job.need_id, job.request_id, job.orchestration_id, job.target_position, job.canary_cohort, job.operation_kind, job.operation_name, job.operation_revision, job.mode, job.input_schema_hash, job.output_schema_hash, job.input_payload, job.status, job.idempotency_key, job.cancel_requested_at, job.deadline_at, job.output_payload, job.error_code, job.error_message, job.started_at, job.completed_at, job.created_at, job.updated_at, job.request_hash
), failed_transfers AS (
    UPDATE connector_transfers transfer
    SET state = 'failed', error_message = finished.error_message,
        cleanup_after = now(), updated_at = now()
    FROM finished
    WHERE transfer.job_id = finished.id AND transfer.state IN ('prepared', 'completing')
)
SELECT id, connector_id, agent_id, need_id, request_id, orchestration_id, target_position, canary_cohort, operation_kind, operation_name, operation_revision, mode, input_schema_hash, output_schema_hash, input_payload, status, idempotency_key, cancel_requested_at, deadline_at, output_payload, error_code, error_message, started_at, completed_at, created_at, updated_at, request_hash FROM finished
`

